head.script:
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name ins_search
 * @description 전일 채권 표준코드부여종목중 정보문의 미전송종목 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    let queryId = "";
    // 전일 채권 표준코드부여종목중 정보문의 미전송종목 조회
    // param1 => 표준코드 STD_CD
    queryId = "lds.ins.common.select.listUnTrsBndCdInquiry";
    // alert(queryId);
    // "&{P}param01=" + txb_pSTD_CD.value ;

    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
scwin.arrPar = new Array();

/**
 * @method
 * @name getParam
 * @description 전달 값을 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue();
    scwin.arrPar[1] = txb_param2.getValue();
    scwin.arrPar[2] = txb_param3.getValue();
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    await scwin.ins_search();
    txb_param1.hide();
    txb_param2.hide();
    txb_param3.hide();
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    await $c.win.alert(dts_List);
};

/**
 * @method
 * @name btn_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_close_onclick = async function() {
    await $c.win.closePopup();
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    if (rowcount === 0) {
        await $c.win.closePopup();
    }
    // alert('dts_List.OnLoadCompleted('+rowcount+')');

};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    if (row === 0) return;
    txb_param1.setValue(dts_List.getCellData(row, "STD_CD"));
    txb_param2.setValue(dts_List.getCellData(row, "ISU_NM"));
    txb_param3.setValue(dts_List.getCellData(row, "TRNSM_DD"));
    fn_GetPar = scwin.getParam;
    const options = {
        id: "ULDINS30700",
        title: "채권발행정보 정보문의전송조회_INS30700",
        type: "pageFramePopup",
        width: "1300px",
        height: "780px"
    };

    const data = {
        // TO-DO : 팝업으로 전달할 파라미터 설정
    };

    const result = await $c.win.openPopup("/search/ULDINS30700.gfm", options, data);
    // TO-DO : result 값 확인 후 업무 로직 추가
};
